"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["9447"],{6601(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>u,frontMatter:()=>o,contentTitle:()=>h,toc:()=>d,assets:()=>l});var a=JSON.parse('{"id":"m3-how-machines-learn/lesson","title":"Lesson: How Machines Actually Learn \u2014 The Ideas Inside ChatGPT","description":"How did ChatGPT learn to write, and why doesn\'t it learn from your chats?","source":"@site/docs/m3-how-machines-learn/lesson.md","sourceDirName":"m3-how-machines-learn","slug":"/m3-how-machines-learn/lesson","permalink":"/aiml-foundations-site/docs/m3-how-machines-learn/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: How Machines Actually Learn \u2014 The Ideas Inside ChatGPT"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/aiml-foundations-site/docs/m2-language-of-modern-ai/deep-dive"},"next":{"title":"Lab: How Machines Actually Learn \u2014 The Ideas Inside ChatGPT","permalink":"/aiml-foundations-site/docs/m3-how-machines-learn/lab"}}'),s=t(4848),r=t(8453),i=t(7684);let o={sidebar_position:1,title:"Lesson: How Machines Actually Learn \u2014 The Ideas Inside ChatGPT"},h="How Machines Actually Learn \u2014 The Ideas Inside ChatGPT",l={},d=[{value:"How did ChatGPT learn to write, and why doesn&#39;t it learn from your chats?",id:"how-did-chatgpt-learn-to-write-and-why-doesnt-it-learn-from-your-chats",level:2},{value:"Module slides",id:"module-slides",level:2},{value:"Three ways a machine learns",id:"three-ways-a-machine-learns",level:2},{value:"Supervised learning",id:"supervised-learning",level:3},{value:"Unsupervised learning",id:"unsupervised-learning",level:3},{value:"Reinforcement learning",id:"reinforcement-learning",level:3},{value:"Features and the train/test split",id:"features-and-the-traintest-split",level:2},{value:"Training vs inference \u2014 why the model doesn&#39;t learn from your chats",id:"training-vs-inference--why-the-model-doesnt-learn-from-your-chats",level:2},{value:"When learning goes wrong: overfitting, underfitting, and bias-variance",id:"when-learning-goes-wrong-overfitting-underfitting-and-bias-variance",level:2},{value:"What&#39;s next",id:"whats-next",level:2}];function c(e){let n={h1:"h1",h2:"h2",h3:"h3",header:"header",mermaid:"mermaid",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"how-machines-actually-learn--the-ideas-inside-chatgpt",children:"How Machines Actually Learn \u2014 The Ideas Inside ChatGPT"})}),"\n",(0,s.jsx)(n.h2,{id:"how-did-chatgpt-learn-to-write-and-why-doesnt-it-learn-from-your-chats",children:"How did ChatGPT learn to write, and why doesn't it learn from your chats?"}),"\n",(0,s.jsx)(n.p,{children:"You already know from Module 2 that an LLM predicts the next chunk of text, one token at a time.\nBut you type a question and it types back an answer, and if you correct it mid-conversation, it\nseems to adjust. So why does the same model give you the exact same wrong answer again tomorrow,\nin a brand-new conversation, as if today never happened?"}),"\n",(0,s.jsx)(n.p,{children:"Because everything a model knows was decided once, during training, long before you opened a chat\nwindow. What happens inside a conversation is a different process called inference, and the model\ncannot rewire itself while that's happening. To see why, and to see where hallucination and API\ncost actually come from, you need three ideas: how a machine learns a pattern from data, what\nhappens once training stops, and what goes wrong when the learning itself is bad. This module\nbuilds all three, with a real predictor you train yourself."}),"\n",(0,s.jsx)(n.h2,{id:"module-slides",children:"Module slides"}),"\n",(0,s.jsx)(n.p,{children:"Walk this short whiteboard deck for the big picture before the definitions below, or open it\nfullscreen."}),"\n",(0,s.jsx)(i.A,{src:"decks/m3-how-machines-learn.html",title:"M3 \u2014 How Machines Actually Learn"}),"\n",(0,s.jsx)(n.h2,{id:"three-ways-a-machine-learns",children:"Three ways a machine learns"}),"\n",(0,s.jsx)(n.p,{children:"Before a model can predict, generate, or act, it has to learn a pattern from data \u2014 and there are\nexactly three ways to hand it that pattern. Every modern AI system scales one of these three up to\nenormous size, so once you name the pattern in a small example, you'll recognize it inside\nChatGPT too."}),"\n",(0,s.jsx)(n.mermaid,{value:'graph LR\n    SUP["Supervised Learning<br/>learn from labeled examples<br/>(square footage \u2192 price)"] --\x3e|"scaled to text, at massive scale"| PRETRAIN["LLM pre-training & fine-tuning<br/>predict the next word from labeled examples"]\n    UNSUP["Unsupervised Learning<br/>find structure, no labels<br/>(group similar customers)"] --\x3e|"scaled to text"| EMBED["Embeddings<br/>the math behind RAG & semantic search"]\n    RL["Reinforcement Learning<br/>learn from reward & penalty<br/>(trial, error, adjust)"] --\x3e|"applied to LLM answers"| RLHF["RLHF<br/>the step that made ChatGPT helpful"]'}),"\n",(0,s.jsx)(n.h3,{id:"supervised-learning",children:"Supervised learning"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Analogy:"})," imagine training a new hire by handing them ten thousand past support tickets, each\nalready marked with the resolution that actually worked. They read ticket after ticket until they\nstart recognizing the pattern themselves \u2014 a similar complaint comes in next week, and they know\nroughly what to do, even though they never saw that exact ticket before."]}),"\n",(0,s.jsxs)(n.p,{children:["That's ",(0,s.jsx)(n.strong,{children:"supervised learning"}),": you show the model many examples, each paired with the correct\nanswer (the ",(0,s.jsx)(n.strong,{children:"label"}),"), and it learns the mapping between the two. Predicting a house's sale price\nfrom its square footage, bedrooms, and location is supervised learning \u2014 the labels are past sale\nprices you already know."]}),"\n",(0,s.jsx)(n.p,{children:'Why you care: this is literally how LLMs are pre-trained and fine-tuned. Pre-training feeds the\nmodel billions of sentences where the "label" for each chunk of text is simply the next chunk \u2014\npredict what comes next, check it against what actually came next, adjust. Fine-tuning does the\nsame thing on a smaller, curated set of examples of the exact behavior you want.'}),"\n",(0,s.jsx)(n.h3,{id:"unsupervised-learning",children:"Unsupervised learning"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Analogy:"}),' now imagine handing that same new hire ten thousand customer records with no\ncategories attached \u2014 no "high value," no "at risk," nothing. Left alone, they\'d still start\nnoticing groups: customers who buy the same three products together, customers who only shop\nduring a sale. Nobody told them the groups existed. They found the structure themselves.']}),"\n",(0,s.jsxs)(n.p,{children:["That's ",(0,s.jsx)(n.strong,{children:"unsupervised learning"}),": there are no labels, so the model looks for structure in the\ndata on its own \u2014 which points naturally cluster together, which sit far apart. Grouping\ncustomers by purchase behavior for a marketing campaign, with no predefined segments handed to\nthe algorithm, is a classic case."]}),"\n",(0,s.jsxs)(n.p,{children:["Why you care: this becomes ",(0,s.jsx)(n.strong,{children:"embeddings"}),", the M2 term for turning text into a point in space,\npositioned so similar meanings land close together. That's unsupervised structure-finding, run on\nlanguage instead of purchase histories \u2014 the technology underneath RAG and semantic search\nfinding the right document without you typing its exact words."]}),"\n",(0,s.jsx)(n.h3,{id:"reinforcement-learning",children:"Reinforcement learning"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Analogy:"}),' think about training a dog with treats and corrections. Nobody shows the dog a\nlabeled dataset of "correct sits." It tries something, gets a reward or doesn\'t, and adjusts what\nit tries next time. Repeat that enough times and the behavior you wanted starts to stick.']}),"\n",(0,s.jsxs)(n.p,{children:["That's ",(0,s.jsx)(n.strong,{children:"reinforcement learning"}),": an agent takes an action, gets a reward or a penalty as\nfeedback, and gradually learns which actions lead to more reward \u2014 no pre-labeled correct answer\nfor every situation, just consequences, tried and adjusted over and over."]}),"\n",(0,s.jsxs)(n.p,{children:["Why you care: this is the ",(0,s.jsx)(n.strong,{children:"RLHF"})," step \u2014 reinforcement learning from human feedback \u2014 that\nturned a raw text-predictor into something that answers helpfully and refuses harmful requests. A\nmodel with only supervised pre-training would still just predict plausible next text; RLHF is the\nreward-and-penalty pass that shapes those predictions into a model worth talking to."]}),"\n",(0,s.jsx)(n.h2,{id:"features-and-the-traintest-split",children:"Features and the train/test split"}),"\n",(0,s.jsxs)(n.p,{children:["For any of these three to work, the machine needs data broken into ",(0,s.jsx)(n.strong,{children:"features"}),": the individual\nmeasurable inputs it learns from \u2014 square footage, bedrooms, and location for a house, or\npurchase frequency and order size for a customer. Features are the columns; each row is one\nexample."]}),"\n",(0,s.jsxs)(n.p,{children:["Here's a mistake that quietly ruins a model's credibility: training it and testing it on the same\ndata. Study for an exam using the actual questions and you'll score near 100 percent \u2014 proving\nnothing about whether you learned the subject. The fix is a ",(0,s.jsx)(n.strong,{children:"train/test split"}),": hold back a\nportion of your data the model never sees during training, then use it afterward to check\nperformance on examples it genuinely never saw. You'll make this exact split in today's lab, and\nthe gap between your training score and your test score is the most honest number you'll get out\nof the model."]}),"\n",(0,s.jsx)(n.h2,{id:"training-vs-inference--why-the-model-doesnt-learn-from-your-chats",children:"Training vs inference \u2014 why the model doesn't learn from your chats"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Training"})," is the phase where the model actually adjusts itself: it sees examples, compares its\nguess to the right answer, and updates its internal numbers to do a little better next time. This\nhappens once, offline, over hours, days, or weeks of compute."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Inference"})," is every time you use the trained model afterward: input in, output out, using the\nexact same fixed numbers it finished training with. Nothing you say during inference changes\nthose numbers. That's the answer to this lesson's opening question \u2014 your conversation with\nChatGPT is entirely inference. It can look like it's \"learning\" your correction within one\nconversation, because that correction is sitting right there in the context window it can read\nfrom, but the moment the conversation ends, the model is exactly as it was before you typed a\nword, ready for the next person with the numbers unchanged."]}),"\n",(0,s.jsx)(n.p,{children:"This also explains why an API call costs money. Training is one large, one-time cost the provider\nabsorbs. Inference is what you're actually paying for, per call, measured in the tokens (M2's\nterm) you send in and get back \u2014 every message is a fresh, metered pass through a model that\nretains nothing from the last one."}),"\n",(0,s.jsx)(n.h2,{id:"when-learning-goes-wrong-overfitting-underfitting-and-bias-variance",children:"When learning goes wrong: overfitting, underfitting, and bias-variance"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Overfitting"})," is what happens when a model learns the training data too well, including its\nnoise and quirks, instead of the general pattern underneath. Picture a student who memorizes last\nyear's exact exam paper, word for word \u2014 they'll ace a repeat of that paper and fail almost any\nreal exam that asks the same material a different way. ",(0,s.jsx)(n.strong,{children:"Underfitting"})," is the opposite failure:\nthe model never learned enough of the pattern, and performs poorly even on the data it trained\non \u2014 that same student, having barely opened the textbook, does badly on both the practice exam\nand the real one."]}),"\n",(0,s.jsxs)(n.p,{children:["Between these two sits the ",(0,s.jsx)(n.strong,{children:"bias-variance trade-off"}),": a model with high bias is too simple and\nunderfits, missing real patterns; a model with high variance is too sensitive and overfits,\ntreating noise as signal. You'll watch that trade-off show up as real numbers in today's lab."]}),"\n",(0,s.jsxs)(n.p,{children:["Why you care: this is the root cause of ",(0,s.jsx)(n.strong,{children:"hallucination"})," (M2's term). A model that overfit its\ntraining data, or never saw enough examples covering a topic, has no real pattern to fall back on\nonce you ask it something outside what it learned well \u2014 so it generates the most statistically\nplausible-sounding text anyway, confident tone included, whether or not it's true. Hallucination\nisn't a separate, mysterious bug bolted onto language models. It's overfitting and underfitting,\nat internet scale, showing up as a sentence instead of a wrong number."]}),"\n",(0,s.jsx)(n.h2,{id:"whats-next",children:"What's next"}),"\n",(0,s.jsx)(n.p,{children:"You now have the three ways a machine learns, and why training and inference stay permanently\nseparate. Module 4 opens the actual toolbox \u2014 the specific algorithms, regression, decision\ntrees, and a single neuron, that put these ideas into practice, including the exact one that\nscales up into everything from here on."})]})}function u(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},7684(e,n,t){t.d(n,{A:()=>r});var a=t(4848);t(6540);var s=t(6497);function r({src:e,title:n="Slides"}){let t=(0,s.Ay)(e);return(0,a.jsxs)("div",{className:"deck_nWXz",children:[(0,a.jsxs)("div",{className:"bar_dOoE",children:[(0,a.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,a.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,a.jsx)("div",{className:"frame_M4DO",children:(0,a.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>o});var a=t(6540);let s={},r=a.createContext(s);function i(e){let n=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),a.createElement(r.Provider,{value:n},e.children)}}}]);